import {validateProofPhoto} from './photos.js';
import {reporterLabel} from './reporter.js';
import {communityPreview} from './community.js';
import {upgradePrototype} from './migrations.js';
import {initialPrototype} from '../../data/prototype.js';
import {categories} from '../../data/mock.js';
import {encodePassword,passwordDigest} from './passwords.js';
import {transitionClaim,closeReportedItem} from './workflow.js';
export const STORAGE_KEY = 'lostchain-prototype-v1';
const uid = prefix => `${prefix}-${crypto.randomUUID()}`;
const clean = (value, label, min=1, max=200) => {
  if (typeof value !== 'string' || value.trim().length < min || value.length > max) throw new Error(`${label} must contain ${min}–${max} characters.`);
  return value.trim();
};
const emailValue = value => {const email=clean(value,'Campus email',3,254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid campus email.');return email};
const safeUser = member => {if(!member)return null;const {credential,...user}=member;return user};
export function createPrototypeRepository(storage) {
  function read() {
    const raw=storage.getItem(STORAGE_KEY);
    if(!raw){const state=initialPrototype();save(state);return state}
    const state=JSON.parse(raw);
    if(![1,2,3,4].includes(state.version) || !['users','items','claims','activities','notifications'].every(key=>Array.isArray(state[key])))throw new Error('Saved prototype data could not be read. Export or clear this site’s storage to start again.');
    const upgraded=upgradePrototype(state);
    if(upgraded!==state)save(upgraded);
    return upgraded;
  }
  function save(state) {try{storage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{throw new Error('Browser storage is full or unavailable. Try a smaller photo or free space before saving.')}}
  const actor = state => {const user=state.users.find(u=>u.address===state.activeAddress);if(!user)throw new Error('Please sign in to continue.');return user};
  function event(state, user, text, recipients=[],claimId=null) {
    const date=new Date().toISOString();
    state.activities.unshift({id:uid('A'),actor:user.address,participants:[user.address,...recipients],text,date,claimId});
    for(const recipient of new Set(recipients.filter(address=>address!==user.address)))state.notifications.unshift({id:uid('N'),recipient,text,claimId,date,read:false});
  }
  function snapshot() {const state=read();const user=state.users.find(u=>u.address===state.activeAddress);const own=state.items.filter(i=>i.reporter===user?.address).map(i=>i.id);return {newReportIds:[...new Set(state.notifications.filter(n=>n.recipient===user?.address&&n.kind==='report'&&!n.read&&state.items.some(i=>i.id===n.itemId)).map(n=>n.itemId))],community:communityPreview(state.users),items:state.items,claims:user?state.claims.filter(c=>c.owner===user.address||own.includes(c.itemId)):[],user:safeUser(user),notifications:state.notifications.filter(n=>n.recipient===user?.address),activities:state.activities.filter(a=>a.participants.includes(user?.address))}}
  return {
    snapshot,
    async register(data){const email=emailValue(data.email),name=clean(data.name,'Name',1,100);if(!['Student','Staff'].includes(data.role))throw new Error('Choose Student or Staff.');if(typeof data.password!=='string'||data.password.length<8||data.password.length>128)throw new Error('Use a password of 8–128 characters.');const credential=await encodePassword(data.password);const state=read();if(state.users.some(u=>u.email===email))throw new Error('This email is already registered. Sign in instead.');const address='LC-'+crypto.randomUUID();const member={name,email,role:data.role,address,credential,registrationStatus:'Registered',registeredAt:new Date().toISOString()};state.users.push(member);state.activeAddress=address;event(state,member,'Joined the campus community.');save(state);return safeUser(member)},
    async login(data){const email=emailValue(data.email);const found=read().users.find(u=>u.email===email);if(!found||typeof data.password!=='string'||await passwordDigest(data.password,found.credential.salt)!==found.credential.digest)throw new Error('Incorrect email or password.');const state=read();state.activeAddress=found.address;save(state);return safeUser(found)},
    logout(){const state=read();state.activeAddress=null;save(state)},
    updateProfile(data){const state=read(),user=actor(state);const name=clean(data.name,'Name',1,100);const email=emailValue(data.email);if(state.users.some(u=>u.address!==user.address&&u.email===email))throw new Error('This email is already in use.');if(!['Student','Staff'].includes(data.role))throw new Error('Choose Student or Staff.');Object.assign(user,{name,email,role:data.role});event(state,user,'Updated profile information.');save(state);return safeUser(user)},
    createItem(data){const state=read(),user=actor(state);if(!['Lost','Found'].includes(data.status)||!categories.includes(data.category))throw new Error('Choose a valid category and report type.');const date=clean(data.date,'Date',10,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date||date>new Date().toISOString().slice(0,10))throw new Error('Choose a valid date, today or earlier.');const image=data.image||'';if(typeof image!=='string'||image.length>2900000||(image&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(image)))throw new Error('Choose a PNG, JPG or WebP photo smaller than 2 MB.');const reporterVisibility=data.reporterVisibility??'anonymous';if(!['anonymous','name'].includes(reporterVisibility))throw new Error('Choose whether to show your name or remain anonymous.');const item={reporterVisibility,...(reporterVisibility==='name'?{reporterName:user.name}:{}),id:uid('LC'),name:clean(data.name,'Item name',1,100),description:clean(data.description,'Description',1,2000),category:data.category,location:clean(data.location,'Location'),status:data.status,reportType:data.status,date,image,createdAt:new Date().toISOString(),reporter:user.address};state.items.unshift(item);event(state,user,`Reported ${item.name} as ${item.status.toLowerCase()}.`);for(const member of state.users.filter(member=>member.address!==user.address)){state.notifications.unshift({id:uid('N'),kind:'report',itemId:item.id,recipient:member.address,text:`${reporterLabel(item)} reported a ${item.status.toLowerCase()} item: ${item.name}.`,date:item.createdAt,read:false})}save(state);return item},
    createClaim(data){const state=read(),user=actor(state),item=state.items.find(i=>i.id===data.itemId);if(!item||item.status!=='Found'||item.reporter===user.address)throw new Error('You can only claim another member’s available found item.');if(state.claims.some(c=>c.itemId===item.id&&c.owner===user.address))throw new Error('You already submitted a claim for this item.');if(state.claims.some(c=>c.itemId===item.id&&c.status==='Accepted'))throw new Error('A handover is already arranged for this item.');const claim={id:uid('CL'),itemId:item.id,owner:user.address,name:user.name,evidence:clean(data.evidence,'Ownership details',15,2000),evidencePhoto:validateProofPhoto(data.evidencePhoto),date:new Date().toISOString().slice(0,10),status:'Pending'};state.claims.unshift(claim);event(state,user,`${user.name} submitted a claim for ${item.name}.`,[item.reporter],claim.id);save(state);return claim},
    claimAction(claimId,action){let state=read();const user=actor(state);const before=state;state=transitionClaim(state,user,claimId,action);const claim=state.claims.find(c=>c.id===claimId),item=state.items.find(i=>i.id===claim.itemId);const actorName=user.address===item.reporter?reporterLabel(item):user.name;for(const other of state.claims){if(other.id!==claimId&&other.status==='Rejected'&&before.claims.find(c=>c.id===other.id)?.status==='Pending')event(state,user,`Another claim was accepted for ${item.name}. Your request was rejected.`,[other.owner],other.id)}const text={cancel:`${user.name} cancelled the claim for ${item.name}.`,accept:`${actorName} accepted the claim for ${item.name}. Arrange your handover.`,reject:`${actorName} rejected the claim for ${item.name}.`,receive:`${user.name} confirmed receiving ${item.name}.`,handover:`${actorName} confirmed handing over ${item.name}.`}[action];event(state,user,claim.status==='Completed'?`${item.name} has been returned. Both parties confirmed.`:text,[item.reporter,claim.owner],claim.id);save(state);return claim},
    closeItem(itemId){let state=read();const user=actor(state);state=closeReportedItem(state,user,itemId);const item=state.items.find(i=>i.id===itemId);const cancelled=state.claims.filter(c=>c.itemId===itemId&&c.cancelledReason==='The reporter closed this item.');event(state,user,`${reporterLabel(item)} closed ${item.name}.`);for(const claim of cancelled)event(state,user,`${item.name} was closed by the reporter. Your pending claim was cancelled.`,[claim.owner],claim.id);save(state);return item},
    arrangeHandover(claimId,meeting){const state=read(),user=actor(state),claim=state.claims.find(c=>c.id===claimId),item=state.items.find(i=>i.id===claim?.itemId);if(!claim||claim.status!=='Accepted'||![claim.owner,item.reporter].includes(user.address))throw new Error('Only the participants of an accepted claim can arrange a handover.');claim.meeting=clean(meeting,'Handover arrangements',5,500);event(state,user,`${user.address===item.reporter?reporterLabel(item):user.name} updated the handover arrangements for ${item.name}.`,[claim.owner,item.reporter],claim.id);save(state)},
    markReportsSeen(itemIds){const state=read(),user=actor(state);if(!Array.isArray(itemIds))throw new Error('Choose the reports to mark as seen.');state.notifications=state.notifications.map(n=>n.recipient===user.address&&n.kind==='report'&&itemIds.includes(n.itemId)?{...n,read:true}:n);save(state)},
    markNotificationsRead(notificationIds){const state=read(),user=actor(state);if(notificationIds!==undefined&&!Array.isArray(notificationIds))throw new Error('Choose notifications to mark as read.');state.notifications=state.notifications.map(n=>n.recipient===user.address&&(notificationIds===undefined||notificationIds.includes(n.id))?{...n,read:true}:n);save(state)},
  };
}
